RATES = {
    "domestic": (500, 120),
    "near": (1200, 260),
    "europe": (1800, 340),
    "far": (2600, 520),
    "rest": (3200, 640),
}


def zone_for(country):
    return ZONES.get(country.upper(), "rest")


def quote(country, grams):
    """Base rate for the zone plus a per-kilo charge, rounded up to the kilo."""
    base, per_kilo = RATES[zone_for(country)]
    kilos = -(-grams // 1000)
    return base + per_kilo * kilos

