arguments.new:
def test_total_includes_shipping():
    order = Order("US").add("widget", 1000, 400)
    assert order.total() == 1000 + 620


def test_free_shipping_over_threshold():
    order = Order("US").add("widget", 8000, 400)
    assert order.shipping() == 0
    assert order.total() == 8000


def test_no_free_shipping_at_exactly_the_threshold():
    order = Order("US").add("widget", 7500, 400)
    assert order.shipping() == 620


def test_light_far_parcel_pays_flat_rate():
    order = Order("JP").add("widget", 1000, 400)
    assert order.shipping() == 1500


def test_far_parcel_at_the_weight_limit_is_weight_banded():
    order = Order("JP").add("widget", 1000, 500)
    assert order.shipping() == 2600 + 520


def test_heavy_far_parcel_is_weight_banded():
    order = Order("JP").add("widget", 1000, 900)
    assert order.shipping() == 2600 + 520


def test_light_parcel_outside_far_zone_is_unaffected():
    order = Order("CA").add("widget", 1000, 400)
    assert order.shipping() == 1200 + 260


def test_free_shipping_beats_the_far_flat_rate():
    order = Order("JP").add("widget", 8000, 400)
    assert order.shipping() == 0


def test_free_shipping_counts_the_whole_order():
    order = Order("US").add("widget", 4000, 200, 2)
    assert order.subtotal() == 8000
    assert order.shipping() == 0
